import { NextRequest, NextResponse } from 'next/server'
import { z } from 'zod'
import { generateContent } from '@/lib/ai/content-generator'
import { CONTENT_TYPES } from '@/lib/ai/content-types'
import type { ContentType } from '@/lib/ai/content-types'
import { getBrandById } from '@/lib/brands'
import type { Platform } from '@/types'
import { PLATFORMS } from '@/types'

const schema = z.object({
  brandId: z.string().min(1),
  platforms: z.array(z.enum(PLATFORMS as [Platform, ...Platform[]])).min(1),
  contentType: z.enum(Object.keys(CONTENT_TYPES) as [ContentType, ...ContentType[]]),
  topic: z.string().max(500).optional().default(''),
})

export async function POST(req: NextRequest) {
  try {
    const body = await req.json()
    const parsed = schema.safeParse(body)

    if (!parsed.success) {
      return NextResponse.json(
        { success: false, error: parsed.error.issues[0]?.message ?? 'Invalid request' },
        { status: 400 }
      )
    }

    const { brandId, platforms, contentType, topic } = parsed.data

    const brand = await getBrandById(brandId)
    if (!brand) {
      return NextResponse.json({ success: false, error: 'Brand not found' }, { status: 404 })
    }

    const { voice, context } = brand

    const results = await generateContent(platforms, brand.name, voice, context, contentType, topic)

    return NextResponse.json({ success: true, data: results })
  } catch (error) {
    console.error('Content generation error:', error)
    return NextResponse.json(
      { success: false, error: 'Content generation failed. Please try again.' },
      { status: 500 }
    )
  }
}

'use client'

import { useState } from 'react'
import { useRouter } from 'next/navigation'
import type { PostStatus } from '@/types'

interface QueueActionsProps {
  postId: string
  status: PostStatus
}

export function QueueActions({ postId, status }: QueueActionsProps) {
  const router = useRouter()
  const [loading, setLoading] = useState(false)
  const [error, setError] = useState<string | null>(null)

  async function handleCancel() {
    if (!confirm('Cancel this scheduled post?')) return
    setLoading(true)
    setError(null)
    try {
      const res = await fetch(`/api/schedule/${postId}`, { method: 'DELETE' })
      const json = await res.json()
      if (!json.success) {
        setError(json.error ?? 'Failed to cancel.')
        return
      }
      router.refresh()
    } catch {
      setError('Network error.')
    } finally {
      setLoading(false)
    }
  }

  async function handleRetry() {
    setLoading(true)
    setError(null)
    try {
      const res = await fetch(`/api/schedule/retry/${postId}`, { method: 'POST' })
      const json = await res.json()
      if (!json.success) {
        setError(json.error ?? 'Retry failed.')
        return
      }
      router.refresh()
    } catch {
      setError('Network error.')
    } finally {
      setLoading(false)
    }
  }

  return (
    <div className="flex items-center gap-2 flex-wrap">
      {status === 'PENDING' && (
        <>
          <a
            href={`/schedule/edit/${postId}`}
            className="text-xs text-slate-300 hover:text-white border border-slate-700 hover:border-slate-500 rounded px-2 py-0.5 transition-colors"
          >
            Edit
          </a>
          <button
            onClick={handleCancel}
            disabled={loading}
            className="text-xs text-red-400 hover:text-red-300 border border-red-800/50 hover:border-red-600/50 rounded px-2 py-0.5 transition-colors disabled:opacity-50"
          >
            {loading ? 'Cancelling...' : 'Cancel'}
          </button>
        </>
      )}

      {status === 'FAILED' && (
        <button
          onClick={handleRetry}
          disabled={loading}
          className="text-xs text-yellow-400 hover:text-yellow-300 border border-yellow-800/50 hover:border-yellow-600/50 rounded px-2 py-0.5 transition-colors disabled:opacity-50"
        >
          {loading ? 'Retrying...' : 'Retry'}
        </button>
      )}

      {error && (
        <span className="text-xs text-red-400">{error}</span>
      )}
    </div>
  )
}

import { describe, it, expect } from 'vitest'
import { assessReplyRisk } from './risk-filter'

describe('assessReplyRisk', () => {
  it('returns LOW with no flags for a benign exchange', () => {
    const result = assessReplyRisk(
      'How do I register my new blender?',
      'Great question! Head to the setup page and follow the three steps.'
    )
    expect(result.riskLevel).toBe('LOW')
    expect(result.flags).toEqual([])
    expect(result.requiresHumanReview).toBe(false)
  })

  it('flags HIGH when the comment contains a legal threat', () => {
    const result = assessReplyRisk(
      'I am going to sue you, this is fraud!',
      'Sorry to hear that â€” let me connect you with our support team.'
    )
    expect(result.riskLevel).toBe('HIGH')
    expect(result.requiresHumanReview).toBe(true)
    expect(result.flags.some((f) => f.startsWith('High-risk terms detected'))).toBe(true)
  })

  it('flags HIGH when the comment demands a refund or chargeback', () => {
    expect(assessReplyRisk('I want a refund now', 'Understood.').riskLevel).toBe('HIGH')
    expect(assessReplyRisk('I will file a chargeback', 'Okay.').riskLevel).toBe('HIGH')
  })

  it('escalates to HIGH when the DRAFT contains commitment language even if the comment is benign', () => {
    const result = assessReplyRisk(
      'Does this come with a warranty?',
      'Yes, we guarantee a full refund if it ever breaks.'
    )
    expect(result.riskLevel).toBe('HIGH')
    expect(result.requiresHumanReview).toBe(true)
    expect(
      result.flags.some((f) => f.startsWith('Draft reply contains commitment language'))
    ).toBe(true)
  })

  it('returns MEDIUM for sensitive complaint language without legal/commitment terms', () => {
    const result = assessReplyRisk(
      'The product arrived broken and defective',
      'So sorry about that â€” here is how to get a replacement.'
    )
    expect(result.riskLevel).toBe('MEDIUM')
    expect(result.requiresHumanReview).toBe(true)
    expect(result.flags.some((f) => f.startsWith('Sensitive terms detected'))).toBe(true)
  })

  it('is case-insensitive when matching keywords', () => {
    const result = assessReplyRisk('This is a SCAM and FRAUD', 'Let me help.')
    expect(result.riskLevel).toBe('HIGH')
  })

  it('matches multi-word phrases like "class action" and "does not work"', () => {
    expect(assessReplyRisk('we are starting a class action', 'ok').riskLevel).toBe('HIGH')
    expect(assessReplyRisk('the app does not work at all', 'ok').riskLevel).toBe('MEDIUM')
  })

  it('scans both the comment and the draft reply for high-risk terms', () => {
    const result = assessReplyRisk(
      'Just a normal question',
      'You should contact the Better Business Bureau.'
    )
    expect(result.riskLevel).toBe('HIGH')
  })

  it('lists every matched high-risk term in the flag', () => {
    const result = assessReplyRisk('scam and fraud and lawsuit', 'ok')
    const highFlag = result.flags.find((f) => f.startsWith('High-risk terms detected'))
    expect(highFlag).toBeDefined()
    expect(highFlag).toContain('scam')
    expect(highFlag).toContain('fraud')
    expect(highFlag).toContain('lawsuit')
  })

  it('prioritises HIGH over MEDIUM when both are present', () => {
    const result = assessReplyRisk(
      'the product is broken and I will sue',
      'ok'
    )
    expect(result.riskLevel).toBe('HIGH')
    // both a sensitive and a high-risk flag should be present
    expect(result.flags.some((f) => f.startsWith('Sensitive terms detected'))).toBe(true)
    expect(result.flags.some((f) => f.startsWith('High-risk terms detected'))).toBe(true)
  })
})

import type { CommentFetchResult } from './types'

const LINKEDIN_API_BASE = 'https://api.linkedin.com/v2'
const LINKEDIN_VERSION = '202312'

async function fetchLinkedInJson(url: string, accessToken: string): Promise<Record<string, unknown>> {
  const response = await fetch(url, {
    headers: {
      Authorization: `Bearer ${accessToken}`,
      'LinkedIn-Version': LINKEDIN_VERSION,
      'X-Restli-Protocol-Version': '2.0.0',
    },
  })

  const text = await response.text()
  let payload: Record<string, unknown> = {}
  try {
    payload = text ? (JSON.parse(text) as Record<string, unknown>) : {}
  } catch {
    payload = {}
  }

  if (!response.ok) {
    const message =
      (typeof payload.message === 'string' && payload.message) ||
      text ||
      `HTTP ${response.status}`
    throw new Error(`LinkedIn API error: ${message}`)
  }

  return payload
}

interface RawLinkedInComment {
  id?: string
  message?: { text?: string }
  actor?: string                 // URN like "urn:li:person:XXXX"
  created?: { time?: number }
}

function extractPersonId(actorUrn: string | undefined): string {
  if (!actorUrn) return 'unknown'
  const parts = actorUrn.split(':')
  return parts[parts.length - 1] ?? actorUrn
}

export async function fetchLinkedInComments(params: {
  accessToken: string
  postUrn?: string
  limit?: number
}): Promise<CommentFetchResult> {
  const postUrn = params.postUrn ?? ''
  const empty: CommentFetchResult = {
    platform: 'LINKEDIN',
    postUrl: postUrn
      ? `https://www.linkedin.com/feed/update/${encodeURIComponent(postUrn)}/`
      : 'https://www.linkedin.com',
    comments: [],
  }

  if (!postUrn) return empty

  try {
    const limit = params.limit ?? 50
    const encodedUrn = encodeURIComponent(postUrn)
    const url =
      `${LINKEDIN_API_BASE}/socialActions/${encodedUrn}/comments` +
      `?count=${limit}`

    const payload = await fetchLinkedInJson(url, params.accessToken)
    const rawElements = Array.isArray(payload.elements)
      ? (payload.elements as RawLinkedInComment[])
      : []

    const comments = rawElements.flatMap((el): CommentFetchResult['comments'] => {
      const text = el.message?.text
      if (!el.id || !text) return []
      return [
        {
          commentId: el.id,
          text,
          authorName: extractPersonId(el.actor),
          authorHandle: el.actor,
          createdAt: el.created?.time
            ? new Date(el.created.time).toISOString()
            : undefined,
        },
      ]
    })

    return {
      ...empty,
      postUrl: `https://www.linkedin.com/feed/update/${encodeURIComponent(postUrn)}/`,
      comments,
    }
  } catch {
    return empty
  }
}

import { prisma } from '@/lib/db'
import { publishPost } from '@/lib/social/index'
import type { PostStatus } from '@/types'

interface PlatformResult {
  success: boolean
  postId?: string
  postUrl?: string
  error?: string
  requiresAuth?: boolean
}

export interface ProcessedPostResult {
  postId: string
  status: PostStatus
  platformResults: Record<string, PlatformResult>
  error?: string
}

function parsePlatforms(raw: string): string[] {
  try {
    const parsed = JSON.parse(raw)
    return Array.isArray(parsed) ? parsed : []
  } catch {
    return []
  }
}

function parseMediaUrls(raw: string): string[] {
  try {
    const parsed = JSON.parse(raw)
    return Array.isArray(parsed) ? parsed : []
  } catch {
    return []
  }
}

export async function processScheduledPosts(): Promise<ProcessedPostResult[]> {
  const now = new Date()

  const pendingPosts = await prisma.scheduledPost.findMany({
    where: {
      status: 'PENDING',
      scheduledAt: { lte: now },
    },
    orderBy: { scheduledAt: 'asc' },
  })

  const results: ProcessedPostResult[] = []

  for (const post of pendingPosts) {
    await prisma.scheduledPost.update({
      where: { id: post.id },
      data: { status: 'PUBLISHING' },
    })

    const platforms = parsePlatforms(post.platforms)
    const mediaUrls = parseMediaUrls(post.mediaUrls)

    let platformResults: Record<string, PlatformResult> = {}

    try {
      platformResults = await publishPost({
        brandId: post.brandId,
        platforms,
        content: post.content,
        mediaUrls,
      })
    } catch (err) {
      const errorMessage = err instanceof Error ? err.message : 'Unexpected publishing error'

      await prisma.scheduledPost.update({
        where: { id: post.id },
        data: { status: 'FAILED', error: errorMessage, results: '{}' },
      })

      results.push({
        postId: post.id,
        status: 'FAILED',
        platformResults: {},
        error: errorMessage,
      })

      continue
    }

    const allFailed =
      platforms.length === 0 ||
      Object.values(platformResults).every((r) => !r.success)

    const anySuccess = Object.values(platformResults).some((r) => r.success)

    const finalStatus: PostStatus = allFailed ? 'FAILED' : 'PUBLISHED'

    const errorMessage = allFailed
      ? Object.values(platformResults)
          .map((r) => r.error)
          .filter(Boolean)
          .join('; ') || 'All platforms failed'
      : undefined

    await prisma.scheduledPost.update({
      where: { id: post.id },
      data: {
        status: finalStatus,
        publishedAt: anySuccess ? new Date() : null,
        results: JSON.stringify(platformResults),
        error: errorMessage ?? null,
      },
    })

    results.push({
      postId: post.id,
      status: finalStatus,
      platformResults,
      error: errorMessage,
    })
  }

  return results
}

export async function cancelPost(postId: string): Promise<void> {
  const post = await prisma.scheduledPost.findUnique({
    where: { id: postId },
  })

  if (!post) {
    throw new Error(`Post ${postId} not found`)
  }

  if (post.status !== 'PENDING') {
    throw new Error(
      `Cannot cancel post ${postId} â€” current status is ${post.status}. Only PENDING posts can be cancelled.`
    )
  }

  await prisma.scheduledPost.update({
    where: { id: postId },
    data: { status: 'CANCELLED' },
  })
}

import type { CommentFetchResult } from './types'

const GRAPH_API_VERSION = 'v19.0'
const GRAPH_BASE = `https://graph.facebook.com/${GRAPH_API_VERSION}`

async function fetchGraphJson(url: string): Promise<Record<string, unknown>> {
  const response = await fetch(url)
  const text = await response.text()

  let payload: Record<string, unknown> = {}
  try {
    payload = text ? (JSON.parse(text) as Record<string, unknown>) : {}
  } catch {
    payload = {}
  }

  if (!response.ok) {
    const errorRecord =
      payload.error && typeof payload.error === 'object' && !Array.isArray(payload.error)
        ? (payload.error as Record<string, unknown>)
        : {}
    const message =
      (typeof errorRecord.message === 'string' && errorRecord.message) ||
      text ||
      `HTTP ${response.status}`
    throw new Error(`Instagram Graph API error: ${message}`)
  }

  return payload
}

interface RawIgComment {
  id?: string
  text?: string
  username?: string
  timestamp?: string
}

interface RawIgMedia {
  id?: string
  caption?: string
  timestamp?: string
  permalink?: string
  comments?: { data?: RawIgComment[] }
}

export async function fetchInstagramComments(params: {
  igUserId: string
  accessToken: string
  limit?: number
}): Promise<CommentFetchResult[]> {
  try {
    const limit = params.limit ?? 10
    const url =
      `${GRAPH_BASE}/${params.igUserId}/media` +
      `?fields=id,caption,timestamp,permalink,comments{id,text,username,timestamp}` +
      `&limit=${limit}` +
      `&access_token=${encodeURIComponent(params.accessToken)}`

    const payload = await fetchGraphJson(url)
    const rawMedia = Array.isArray(payload.data)
      ? (payload.data as RawIgMedia[])
      : []

    return rawMedia
      .filter((media) => media.id != null)
      .map((media): CommentFetchResult => {
        const postUrl =
          media.permalink ??
          `https://www.instagram.com/p/${media.id}/`

        const rawComments = media.comments?.data ?? []
        const comments = rawComments.flatMap((c): CommentFetchResult['comments'] => {
          if (!c.id || !c.text) return []
          return [
            {
              commentId: c.id,
              text: c.text,
              authorName: c.username ?? 'Unknown',
              authorHandle: c.username,
              createdAt: c.timestamp,
            },
          ]
        })

        return {
          platform: 'INSTAGRAM',
          postUrl,
          postContent: media.caption,
          comments,
        }
      })
      .filter((r) => r.comments.length > 0)
  } catch {
    return []
  }
}

import type { CommentFetchResult } from './types'

const TIKTOK_API_BASE = 'https://open.tiktokapis.com/v2'

async function fetchTikTokJson(url: string, accessToken: string): Promise<Record<string, unknown>> {
  const response = await fetch(url, {
    headers: {
      Authorization: `Bearer ${accessToken}`,
      'Content-Type': 'application/json',
    },
  })

  const text = await response.text()
  let payload: Record<string, unknown> = {}
  try {
    payload = text ? (JSON.parse(text) as Record<string, unknown>) : {}
  } catch {
    payload = {}
  }

  if (!response.ok) {
    const errObj =
      payload.error && typeof payload.error === 'object'
        ? (payload.error as Record<string, unknown>)
        : {}
    const message =
      (typeof errObj.message === 'string' && errObj.message) ||
      text ||
      `HTTP ${response.status}`
    throw new Error(`TikTok API error: ${message}`)
  }

  return payload
}

interface RawTikTokComment {
  id?: string
  text?: string
  like_count?: number
  create_time?: number
  username?: string
}

export async function fetchTikTokComments(params: {
  accessToken: string
  videoId: string
  limit?: number
}): Promise<CommentFetchResult> {
  const postUrl = `https://www.tiktok.com/@video/video/${params.videoId}`
  const empty: CommentFetchResult = {
    platform: 'TIKTOK',
    postUrl,
    comments: [],
  }

  if (!params.videoId) return empty

  try {
    const maxCount = Math.min(params.limit ?? 50, 100)
    const fields = 'id,text,like_count,create_time,username'
    const url =
      `${TIKTOK_API_BASE}/video/comment/list/` +
      `?fields=${encodeURIComponent(fields)}` +
      `&video_id=${encodeURIComponent(params.videoId)}` +
      `&max_count=${maxCount}`

    const payload = await fetchTikTokJson(url, params.accessToken)

    // TikTok wraps response in { data: { comments: [...] } }
    const dataObj =
      payload.data && typeof payload.data === 'object'
        ? (payload.data as Record<string, unknown>)
        : {}

    const rawComments = Array.isArray(dataObj.comments)
      ? (dataObj.comments as RawTikTokComment[])
      : Array.isArray(payload.comments)
        ? (payload.comments as RawTikTokComment[])
        : []

    const comments = rawComments.flatMap((c): CommentFetchResult['comments'] => {
      if (!c.id || !c.text) return []
      return [
        {
          commentId: c.id,
          text: c.text,
          authorName: c.username ?? 'Unknown',
          authorHandle: c.username ? `@${c.username}` : undefined,
          createdAt: c.create_time
            ? new Date(c.create_time * 1000).toISOString()
            : undefined,
        },
      ]
    })

    return { ...empty, comments }
  } catch {
    return empty
  }
}

import { NextRequest, NextResponse } from 'next/server'
import { prisma } from '@/lib/db'
import type { ApiResponse } from '@/types'

interface SkipResponseData {
  opportunityId: string
  status: string
  updatedAt: string
}

export async function POST(
  _request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
): Promise<NextResponse> {
  const { id } = await params
  const opportunity = await prisma.commentOpportunity.findUnique({
    where: { id },
  })

  if (!opportunity) {
    const response: ApiResponse<never> = {
      success: false,
      error: 'Comment opportunity not found',
    }
    return NextResponse.json(response, { status: 404 })
  }

  if (opportunity.status === 'POSTED') {
    const response: ApiResponse<never> = {
      success: false,
      error: 'Cannot skip an already-posted opportunity',
    }
    return NextResponse.json(response, { status: 422 })
  }

  const updated = await prisma.commentOpportunity.update({
    where: { id: id },
    data: { status: 'SKIPPED' },
  })

  const response: ApiResponse<SkipResponseData> = {
    success: true,
    data: {
      opportunityId: updated.id,
      status: updated.status,
      updatedAt: updated.updatedAt.toISOString(),
    },
  }

  return NextResponse.json(response)
}

import { NextRequest, NextResponse } from 'next/server'
import { z } from 'zod'
import { scanCommentsForBrand } from '@/lib/comments'
import type { ApiResponse } from '@/types'

const ScanBodySchema = z.object({
  brandId: z.string().min(1),
  platforms: z.array(z.string()).optional(),
  additionalUrls: z
    .array(
      z.object({
        platform: z.string().min(1),
        // Accepts a full post URL *or* a raw identifier (LinkedIn URN,
        // TikTok video id), so this is validated as non-empty rather than a URL.
        url: z.string().min(1),
        relevanceNote: z.string().optional(),
      })
    )
    .optional(),
})

export async function POST(request: NextRequest): Promise<NextResponse> {
  try {
    const body: unknown = await request.json()
    const parsed = ScanBodySchema.safeParse(body)

    if (!parsed.success) {
      const response: ApiResponse<never> = {
        success: false,
        error: parsed.error.issues.map((i) => i.message).join(', '),
      }
      return NextResponse.json(response, { status: 400 })
    }

    const result = await scanCommentsForBrand(parsed.data)

    const response: ApiResponse<typeof result> = {
      success: true,
      data: result,
    }
    return NextResponse.json(response)
  } catch (error) {
    const response: ApiResponse<never> = {
      success: false,
      error: error instanceof Error ? error.message : 'Scan failed',
    }
    return NextResponse.json(response, { status: 500 })
  }
}

import { NextRequest, NextResponse } from 'next/server'
import { z } from 'zod'
import { prisma } from '@/lib/db'
import type { ApiResponse } from '@/types'

const approveSchema = z.object({
  draftId: z.string().optional(),
  customReply: z.string().min(1).max(10000).optional(),
}).refine(
  (data) => data.draftId !== undefined || data.customReply !== undefined,
  { message: 'Either draftId or customReply must be provided' }
)

interface ApproveResponseData {
  opportunityId: string
  approvedReply: string
  status: string
  updatedAt: string
}

export async function POST(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
): Promise<NextResponse> {
  const { id } = await params
  const opportunity = await prisma.commentOpportunity.findUnique({
    where: { id },
  })

  if (!opportunity) {
    const response: ApiResponse<never> = {
      success: false,
      error: 'Comment opportunity not found',
    }
    return NextResponse.json(response, { status: 404 })
  }

  let body: unknown
  try {
    body = await request.json()
  } catch {
    const response: ApiResponse<never> = { success: false, error: 'Invalid JSON body' }
    return NextResponse.json(response, { status: 400 })
  }

  const parsed = approveSchema.safeParse(body)
  if (!parsed.success) {
    const response: ApiResponse<never> = {
      success: false,
      error: parsed.error.issues.map((i) => i.message).join(', '),
    }
    return NextResponse.json(response, { status: 422 })
  }

  const { draftId, customReply } = parsed.data
  let approvedContent: string

  if (draftId) {
    const draft = await prisma.commentDraft.findUnique({
      where: { id: draftId },
    })

    if (!draft || draft.opportunityId !== id) {
      const response: ApiResponse<never> = {
        success: false,
        error: 'Draft not found for this opportunity',
      }
      return NextResponse.json(response, { status: 404 })
    }

    approvedContent = customReply ?? draft.content

    // Mark this draft as approved
    await prisma.commentDraft.update({
      where: { id: draftId },
      data: { isApproved: true },
    })
  } else {
    // Manual custom reply â€” no draft to mark
    approvedContent = customReply as string
  }

  const updatedOpportunity = await prisma.commentOpportunity.update({
    where: { id: id },
    data: {
      approvedReply: approvedContent,
      status: 'APPROVED',
    },
  })

  const response: ApiResponse<ApproveResponseData> = {
    success: true,
    data: {
      opportunityId: updatedOpportunity.id,
      approvedReply: approvedContent,
      status: updatedOpportunity.status,
      updatedAt: updatedOpportunity.updatedAt.toISOString(),
    },
  }

  return NextResponse.json(response)
}

import { NextRequest, NextResponse } from 'next/server'
import { processScheduledPosts } from '@/lib/scheduler'
import type { ApiResponse } from '@/types'

interface CronResult {
  processed: number
  results: Array<{
    postId: string
    status: string
    platformResults: Record<string, unknown>
    error?: string
  }>
}

async function runScheduler(): Promise<NextResponse> {
  const results = await processScheduledPosts()

  const response: ApiResponse<CronResult> = {
    success: true,
    data: {
      processed: results.length,
      results,
    },
  }

  return NextResponse.json(response)
}

export async function GET(_request: NextRequest): Promise<NextResponse> {
  return runScheduler()
}

export async function POST(_request: NextRequest): Promise<NextResponse> {
  return runScheduler()
}

