import { NextRequest, NextResponse } from 'next/server'
import { processScheduledPosts } from '@/lib/scheduler'
import type { ApiResponse } from '@/types'

interface CronResult {
  processed: number
  results: Array<{
    postId: string
    status: string
    platformResults: Record<string, unknown>
    error?: string
  }>
}

async function runScheduler(): Promise<NextResponse> {
  const results = await processScheduledPosts()

  const response: ApiResponse<CronResult> = {
    success: true,
    data: {
      processed: results.length,
      results,
    },
  }

  return NextResponse.json(response)
}

export async function GET(_request: NextRequest): Promise<NextResponse> {
  return runScheduler()
}

export async function POST(_request: NextRequest): Promise<NextResponse> {
  return runScheduler()
}

'use client'

import Link from 'next/link'
import { usePathname } from 'next/navigation'
import {
  LayoutDashboard,
  Sparkles,
  CalendarPlus,
  ClipboardList,
  MessageSquare,
  Link2,
  Building2,
} from 'lucide-react'
import clsx from 'clsx'

const NAV_ITEMS = [
  { href: '/', label: 'Overview', icon: LayoutDashboard },
  { href: '/create', label: 'Content Lab', icon: Sparkles },
  { href: '/schedule', label: 'Schedule', icon: CalendarPlus },
  { href: '/queue', label: 'Queue', icon: ClipboardList },
  { href: '/comments', label: 'Comments', icon: MessageSquare },
  { href: '/brands', label: 'Brands', icon: Building2 },
  { href: '/connect', label: 'Connect', icon: Link2 },
]

export function SidebarNav() {
  const pathname = usePathname()

  return (
    <nav className="flex flex-col gap-1 px-3">
      {NAV_ITEMS.map((item) => {
        const Icon = item.icon
        const isActive =
          item.href === '/' ? pathname === '/' : pathname.startsWith(item.href)

        return (
          <Link
            key={item.href}
            href={item.href}
            className={clsx(
              'flex items-center gap-3 px-3 py-2.5 rounded-md text-sm font-medium transition-colors',
              isActive
                ? 'bg-blue-600 text-white'
                : 'text-slate-400 hover:text-white hover:bg-slate-700'
            )}
          >
            <Icon size={18} strokeWidth={1.75} />
            {item.label}
          </Link>
        )
      })}
    </nav>
  )
}

